/*
 * A285092  Positions of 1 in A284848; complement of A285091.
 * https://oeis.org/A285092
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = position of the n-th 1 in A284848, the Thue-Morse word
 *            with each 1100 replaced by 1 (generated by scan)
 * Range:     u8 n <= 141, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 80 terms through n = 9322 (2026-11-08)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include "../utils/mem.h"

static inline int A285092_tm(idx_t pos)
{
    int p = 0;
    while (pos) { p ^= (int)(pos & 1); pos >>= 1; }
    return p;
}

seq_t a(idx_t n)
{
    static idx_t *pos = NULL;
    static size_t cap = 0;
    static idx_t cnt = 0;
    static idx_t next_input = 0;
    static idx_t out_pos = 0;

    if (n < 1) return (seq_t)0;
    if (!pos) {
        cap = 64;
        pos = mem_new(idx_t, cap);
        if (!pos) return (seq_t)0;
    }
    while (cnt < n) {
        int b0 = A285092_tm(next_input);
        int bit;
        if (b0 == 1 && A285092_tm(next_input + 1) == 1 &&
            A285092_tm(next_input + 2) == 0 && A285092_tm(next_input + 3) == 0) {
            bit = 1;
            next_input += 4;
        } else {
            bit = b0;
            next_input += 1;
        }
        out_pos++;
        if (bit) {
            if ((size_t)cnt == cap) {
                size_t nc = cap * 2;
                idx_t *t = mem_resize(idx_t, pos, nc);
                if (!t) return (seq_t)0;
                pos = t;
                cap = nc;
            }
            pos[cnt++] = out_pos;
        }
    }
    return (seq_t)pos[n - 1];
}
